import{_ as a,o as t,c as e,a3 as _}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-022.HawBy2sH.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/69-他竟然还没把前女友拉黑？.md","filePath":"books/attached/69-他竟然还没把前女友拉黑？.md","lastUpdated":1794298621000}'),s={name:"books/attached/69-他竟然还没把前女友拉黑？.md"};function r(n,p,d,i,c,l){return t(),e("div",null,[...p[0]||(p[0]=[_('<h3 id="他竟然还没把前女友拉黑" tabindex="-1">他竟然还没把前女友拉黑？ <a class="header-anchor" href="#他竟然还没把前女友拉黑" aria-label="Permalink to &quot;他竟然还没把前女友拉黑？&quot;">​</a></h3><p>33岁的内奥米（Naomi）和30岁的凯文（Kevin），热恋半年就出现了一些棘手的问题。内奥米发现凯文还没有将前女友从脸书上拉黑，她对此感到有点儿难过。她还非常断定凯文在和别的女人调情。而另一方面，凯文很不喜欢在和哥们儿出去喝酒的时候，内奥米要不停地对他进行电话轰炸，所以就常常挂掉她的电话。凯文觉得内奥米实在是神经过敏又爱吃醋，他也常常跟内奥米抱怨这一点。内奥米也尝试着控制自己愈演愈烈的猜忌和焦虑，但是无论如何，它们还是挥之不去。</p><p>关于是否应该把前女友从社交网络删除，是否应该保持联系，在恋爱原则中并没有固定的答案。同理，是否应该在男朋友外出社交的时候，不停地打电话给他，也没有什么对错之分。在某些情况之下，这两种行为都是说得过去的。但内奥米和凯文的冲突，根本就不在于这两个问题本身，这也就是两人为什么久久不能达成一致了。两人根本的分歧在于，对亲密关系的要求，以及双方亲密度背后意义的理解完全不一样。回避型依恋风格的凯文，想和内奥米保持一定的距离，因此就会使用各种去激活策略，比如隐藏自己的行踪，或是明知内奥米不能接受，还要和前任保持联系。而内奥米则一心想要打破凯文设在两人之间的这些界限。然而，没有凯文的配合，内奥米的努力只能是徒劳。毕竟亲密感的营造，是一件你情我愿的事情。</p><p>上面的三个例子有一个共同之处，那就是：每当其中一方努力拉近距离，另一方就愈发地感到如坐针毡。这在伴侣其中一方为回避型依恋风格的时候，是非常常见的。其中，相比于遇见安全型依恋风格，当回避型遇到焦虑型的时候，这种情况会更容易发生。</p><p>很多关于依恋的相关研究都表明，每当一个人的亲密需求得到满足，且伴侣给予了同样的回馈，此时的亲密关系满意度就会飙升。而反过来说，不相适应的亲密需求则会显著地导致满意度降低。当伴侣双方在恋爱中的亲密需求上产生分歧时，这件事情产生的威胁，会遍布日常生活中的每一件小事。而这种情况就是所谓的“焦虑——回避型陷阱”，之所以形容为“陷阱”，就是因为它像是个真正的圈套，在两人不经意间产生，一旦陷进去就很难脱身。</p><p>在焦虑——回避型亲密关系中，人们往往很难获得稳固的安全型关系，其中很大一个原因就在于，两人都充满了不安全感，双方的恶性循环，形成了令人窒息的桎梏。我们可以看到接下来的这幅图，位于右下方的焦虑型依恋风格，正在忙于处理自己依恋机制激活而产生的诸多威胁，主要表现为想要无限接近对方。而位于左下方的回避型，则产生了完全对立的反应。他们正在使用去激活策略，想方设法地和伴侣拉开距离，“压制”自己的依恋机制。这样一来，焦虑型的一方紧紧追赶，回避型的一方就尽力躲藏。一方的激活机制向对方的去激活策略步步紧逼，最终形成恶性循环，亲密关系最终万劫不复，遁入“危险地带”。而为了到达图中的“安全地带”，双方建立足够的安全感，双方都需要寻找到减少危机感的方法，一方不要步步紧逼，一方也尽量减少逃避，才能携手走出危险地带。</p><p>焦虑-回避型陷阱的基本要素</p><p>双方的理想情感距离</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>下面是在焦虑——回避型亲密关系中，容易出现的一些典型现象：</p><p>1.“过山车”效应</p><p>你们的关系仿佛没有一刻处于平稳期，总是像过山车一样跌宕起伏。不过，一旦回避型伴侣难得地给焦虑型恋人一点存在和支持，焦虑者的依恋机制就能暂且得到平复，两人的亲密程度也能达到一个“峰值”。不过，这种暂时的亲密感对于回避型人群来说，就是一种威胁。因此，只有重新拉开彼此的距离，消除这种亲密感才能消除威胁，但与此同时，焦虑型一方的不适感又卷土重来。</p><p>2.情感“跷跷板”</p><p>作为一个回避型恋人，你常常感觉自己和别人相比起来更加独立，也会因此自信满满。而作为焦虑型伴侣，你在依恋机制被激活的时候，就会不自觉地感到“低人一等”。在伴侣感觉渴望对方、十分无助的时候，回避型依恋风格的人尤其感觉自己独立自主、充满力量。这也是回避型人群很难对同类型倾心的重要原因之一。当对方同自己一样警觉而防备的时候，他们是很难感到自己的强大与独立的。</p><p>3.长久不稳定</p><p>或许你们的感情已经持续多年，但却一直处于风雨飘摇的境地。正如上一页的图中所见，双方很可能长时间保持着对对方的不满，永远找不到一个令双方都感到舒适的亲密程度。</p><p>4.争吵只是假象</p><p>或许你们总会为一些不足为题的小事争吵。事实上，你们的争吵并不一定真正关乎这些鸡毛蒜皮，你们之间真正的问题在于，双方对亲密程度的不同要求。</p><p>5.最亲密的敌人</p><p>焦虑型依恋风格的人一旦与回避型伴侣建立亲密关系，往往会感受到来自对方的冷漠和敌意。在下一章，我们会深入探讨这个问题。</p><p>6.落入亲密陷阱</p><p>你们会愈发强烈地产生一种可怕的感受，感觉对方完全不适合你，然而一想到对方会离你而去，又会陷入更加强烈的痛苦中。</p>',22)])])}const f=a(s,[["render",r]]);export{h as __pageData,f as default};
